package main

// Reference inputs are transcribed from native-campaign-public.rs. Outputs are
// generated by the Go public campaign API, not read from the frozen oracle.
import (
	"encoding/json"
	"fmt"
	s "github.com/Jagalite/statelessness/go"
	"math"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"time"
)

func u(v uint64) string { return strconv.FormatUint(v, 10) }
func refFuzz(c s.FuzzConfig64) map[string]any {
	return map[string]any{"seed": u(c.Seed), "cases": u(c.Cases), "max_steps": u(c.MaxSteps), "max_transitions": u(c.MaxTransitions), "mutation_percent": strconv.Itoa(c.MutationPercent)}
}
func refConfig(c s.CampaignConfig64) map[string]any {
	return map[string]any{"master_seed": u(c.MasterSeed), "first_job": u(c.FirstJob), "jobs": u(c.Jobs), "workers": u(c.Workers), "result_buffer": u(c.ResultBuffer), "fuzz": refFuzz(c.Fuzz), "stop_on_failure": c.StopOnFailure}
}
func baseReference() s.CampaignConfig64 {
	return s.CampaignConfig64{FirstJob: 7, Jobs: 1, Workers: 1, Fuzz: s.FuzzConfig64{Seed: 999, Cases: 1, MaxSteps: 2, MaxTransitions: 2}}
}

var refSeeds = [][2]uint64{{0, 0}, {0, 1}, {0, 2}, {0, 7}, {0, 42}, {0, math.MaxUint64}, {math.MaxUint64, 0}, {math.MaxUint64, 1}, {1, math.MaxUint64}, {math.MaxUint64, 2}, {2, math.MaxUint64}, {1 << 63, 1 << 63}, {1 << 63, (1 << 63) + 1}, {1 << 53, math.MaxUint64 - (1 << 53) + 1}, {(1 << 53) + 1, math.MaxUint64 - (1 << 53)}}
var refValidations = []string{"jobs-zero", "workers-zero", "workers-257", "buffer-1025", "workers-256", "buffer-1024", "max-id", "id-overflow", "mutation-101", "mutation-100", "aggregate-cases", "aggregate-transitions", "wide-product-capped", "max-job-count-valid", "validation-first-error"}

func referenceValidation(name string) (map[string]any, bool) {
	c := baseReference()
	found := false
	for _, n := range refValidations {
		if n == name {
			found = true
			break
		}
	}
	if !found {
		return nil, false
	}
	const portable uint64 = (1 << 53) - 1
	switch name {
	case "jobs-zero":
		c.Jobs = 0
	case "workers-zero":
		c.Workers = 0
	case "workers-257":
		c.Workers = 257
	case "buffer-1025":
		c.ResultBuffer = 1025
	case "workers-256":
		c.Workers = 256
	case "buffer-1024":
		c.ResultBuffer = 1024
	case "max-id":
		c.FirstJob = math.MaxUint64
	case "id-overflow":
		c.FirstJob = math.MaxUint64
		c.Jobs = 2
	case "mutation-101":
		c.Fuzz.MutationPercent = 101
	case "mutation-100":
		c.Fuzz.MutationPercent = 100
	case "aggregate-cases":
		c.Jobs = 2049
		c.Fuzz.Cases = portable
	case "aggregate-transitions":
		c.Jobs = 2049
		c.Fuzz.MaxSteps = portable
		c.Fuzz.MaxTransitions = math.MaxUint64
	case "wide-product-capped":
		c.Jobs = 2
		c.Fuzz.Cases = portable
		c.Fuzz.MaxSteps = portable
		c.Fuzz.MaxTransitions = 1
	case "max-job-count-valid":
		c.FirstJob = 0
		c.Jobs = portable
		c.Fuzz.MaxSteps = 1
		c.Fuzz.MaxTransitions = 1
	case "validation-first-error":
		c.Jobs = 0
		c.Workers = 0
		c.ResultBuffer = 1025
		c.Fuzz.MutationPercent = 101
	}
	var msg any
	if err := c.Validate(); err != nil {
		msg = err.Error()
	}
	return map[string]any{"schema": "native-campaign-v1", "kind": "validation", "case": name, "config": refConfig(c), "error": msg}, true
}
func emitReference(name string) error {
	var row map[string]any
	if strings.HasPrefix(name, "seed-") {
		i, e := strconv.Atoi(strings.TrimPrefix(name, "seed-"))
		if e != nil || i < 0 || i >= len(refSeeds) || name != fmt.Sprintf("seed-%02d", i) {
			return fmt.Errorf("unknown case %q", name)
		}
		a := refSeeds[i]
		row = map[string]any{"schema": "native-campaign-v1", "kind": "seed", "case": name, "master_seed": u(a[0]), "job_id": u(a[1]), "seed": u(s.JobSeed(a[0], a[1]))}
	} else if v, ok := referenceValidation(name); ok {
		row = v
	} else if v, ok, err := referenceCampaign(name); ok {
		if err != nil {
			return err
		}
		row = v
	} else {
		return fmt.Errorf("unsupported reference case %q", name)
	}
	return json.NewEncoder(os.Stdout).Encode(row)
}

var refCampaigns = []string{"ordinary-basic", "guided-basic", "factory-error", "feedback-error", "factory-cancelled", "pre-cancelled", "deadline-zero", "cases-zero", "steps-zero", "transitions-zero", "initial-error", "step-error", "check-error", "metadata-panic", "feedback-metadata-panic", "drop-panic", "sink-error", "sink-panic", "property-stop"}

func variant(v string) string {
	p := strings.Split(v, "_")
	for i := range p {
		if len(p[i]) > 0 {
			p[i] = strings.ToUpper(p[i][:1]) + p[i][1:]
		}
	}
	return strings.Join(p, "")
}
func metadataJSON(m *s.Metadata) any {
	if m == nil {
		return nil
	}
	return map[string]any{"name": m.Name, "model_version": u(uint64(m.ModelVersion)), "properties_version": u(uint64(m.PropertiesVersion)), "codec_version": u(uint64(m.CodecVersion)), "build": m.Build}
}
func errJSON(e error) any {
	if e == nil {
		return nil
	}
	return e.Error()
}
func fuzzJSON(f *s.FuzzReport64[uint64]) any {
	if f == nil {
		return nil
	}
	var failure any
	if f.Failure != nil {
		inputs := []string{}
		for _, v := range f.Failure.Inputs {
			inputs = append(inputs, u(v))
		}
		vs := []any{}
		for _, v := range f.Failure.Violations {
			status := variant(v.Check.Status)
			if v.Check.Status != "passed" {
				b, _ := json.Marshal(v.Check.Details)
				status += "(" + string(b) + ")"
			}
			vs = append(vs, map[string]any{"phase": variant(v.Phase), "id": v.Check.ID, "status": status})
		}
		failure = map[string]any{"inputs": inputs, "violations": vs}
	}
	var guidance any
	if g := f.Guidance; g != nil {
		corpus := []any{}
		for _, v := range g.Corpus {
			inputs := []string{}
			for _, i := range v.Inputs {
				inputs = append(inputs, u(i))
			}
			corpus = append(corpus, map[string]any{"inputs": inputs, "new_features": u(v.NewFeatures), "discovered_case": u(v.DiscoveredCase), "discovered_transition": u(v.DiscoveredTransition)})
		}
		guidance = map[string]any{"algorithm": g.Algorithm, "config": map[string]any{"max_corpus_entries": u(g.Config.MaxCorpusEntries), "max_corpus_inputs": u(g.Config.MaxCorpusInputs), "max_features": u(g.Config.MaxFeatures), "max_features_per_observation": u(g.Config.MaxFeaturesPerObservation)}, "feedback": map[string]any{"name": g.Feedback.Name, "version": u(uint64(g.Feedback.Version)), "build": g.Feedback.Build}, "unique_features": u(g.UniqueFeatures), "corpus_inputs": u(g.CorpusInputs), "corpus": corpus, "mutation_cases": u(g.MutationCases), "dropped_prefixes": u(g.DroppedPrefixes), "evicted_prefixes": u(g.EvictedPrefixes), "feature_limit_reached": g.FeatureLimitReached, "corpus_limit_reached": g.CorpusLimitReached}
	}
	return map[string]any{"termination": variant(f.Termination), "seed": u(f.Seed), "cases": u(f.Cases), "transitions": u(f.Transitions), "skipped_checks": u(f.SkippedChecks), "failure": failure, "guidance": guidance}
}
func jobJSON(j s.JobReport64[uint64]) map[string]any {
	var err any
	if j.Outcome.Kind == "panicked" {
		err = j.Outcome.Panic
	} else {
		err = errJSON(j.Outcome.Error)
	}
	return map[string]any{"job_id": u(j.JobID), "seed": u(j.Seed), "config": refFuzz(j.Config), "metadata": metadataJSON(j.Metadata), "outcome": variant(j.Outcome.Kind), "error": err, "fuzz": fuzzJSON(j.Outcome.Report)}
}
func reportJSON(r s.CampaignReport64) map[string]any {
	return map[string]any{"requested": u(r.Requested), "started": u(r.Started), "finished": u(r.Finished), "not_started": u(r.NotStarted), "delivered": u(r.Delivered), "failures": u(r.Failures), "errors": u(r.Errors), "reported_transitions": u(r.ReportedTransitions), "reported_cases": u(r.ReportedCases), "reported_skipped_checks": u(r.ReportedSkippedChecks), "accounting_complete": r.AccountingComplete, "termination": variant(r.Termination.Kind), "error": errJSON(r.Termination.Error)}
}
func referenceCampaign(name string) (map[string]any, bool, error) {
	found := false
	for _, n := range refCampaigns {
		if n == name {
			found = true
			break
		}
	}
	if !found {
		return nil, false, nil
	}
	c := baseReference()
	if name == "factory-error" || name == "feedback-error" {
		c.Jobs = 2
		c.StopOnFailure = true
	}
	if name == "property-stop" {
		c.Jobs = 3
		c.StopOnFailure = true
	}
	switch name {
	case "cases-zero":
		c.Fuzz.Cases = 0
	case "steps-zero":
		c.Fuzz.Cases = 2
		c.Fuzz.MaxSteps = 0
		c.Fuzz.MaxTransitions = 0
	case "transitions-zero":
		c.Fuzz.MaxTransitions = 0
	}
	guided := strings.HasPrefix(name, "guided") || name == "feedback-error" || name == "factory-cancelled" || name == "feedback-metadata-panic"
	events := []string{}
	jobs := []any{}
	var cancel atomic.Bool
	if name == "pre-cancelled" {
		cancel.Store(true)
	}
	emit := func(id uint64, event string) { events = append(events, fmt.Sprintf("%d:%s", id, event)) }
	factory := func(id uint64) (s.CampaignModel[uint64, uint64, uint64], error) {
		emit(id, "factory")
		if name == "factory-error" {
			return s.CampaignModel[uint64, uint64, uint64]{}, &s.ModelError{Message: "factory error"}
		}
		if name == "factory-cancelled" {
			cancel.Store(true)
		}
		m := s.Model[uint64, uint64, uint64]{CloneState: s.ValueCopy[uint64], CloneInput: s.ValueCopy[uint64], CloneOutput: s.ValueCopy[uint64], EqualStates: func(a, b uint64) bool { return a == b },
			InitialState: func() (uint64, error) {
				emit(id, "initial")
				if name == "initial-error" {
					return 0, &s.ModelError{Message: "initial error"}
				}
				return 0, nil
			},
			Step: func(state, input uint64) (s.Transition[uint64, uint64], error) {
				emit(id, fmt.Sprintf("step:%d:%d", state, input))
				if name == "step-error" {
					return s.Transition[uint64, uint64]{}, &s.ModelError{Message: "step error"}
				}
				return s.Accept(state+1, input), nil
			},
			CheckState: func(state uint64) ([]s.Check, error) {
				emit(id, fmt.Sprintf("check_state:%d", state))
				if state > 0 && name == "check-error" {
					return nil, &s.ModelError{Message: "check error"}
				}
				c := s.Passed("n06.counter")
				if state == 2 && name == "property-stop" {
					c = s.Failed("n06.counter", "second transition")
				}
				return []s.Check{c, s.Skipped("n06.optional", "fixture")}, nil
			},
			CheckTransition: func(before, input uint64, _ s.Transition[uint64, uint64]) ([]s.Check, error) {
				emit(id, fmt.Sprintf("check_transition:%d:%d", before, input))
				return []s.Check{s.Passed("n06.edge")}, nil
			},
		}
		g := s.GenerateModel[uint64, uint64, uint64]{Model: m, Generate: func(state uint64, _ *s.Rng) (uint64, bool, error) {
			v := state + 1
			emit(id, fmt.Sprintf("generate:%d:%d", state, v))
			return v, true, nil
		}, IsEnabled: func(state, input uint64) (bool, error) {
			emit(id, fmt.Sprintf("enabled:%d:%d", state, input))
			return true, nil
		}}
		return s.CampaignModel[uint64, uint64, uint64]{Model: g, Metadata: func() (s.Metadata, error) {
			emit(id, "metadata")
			if name == "metadata-panic" {
				panic("metadata panic")
			}
			return s.Identity(fmt.Sprintf("n06-counter:%d", id), "n06-counter-v1"), nil
		}, Close: func() error {
			emit(id, "model_drop")
			if name == "drop-panic" {
				panic("model drop")
			}
			return nil
		}}, nil
	}
	feedback := func(id uint64, _ s.GenerateModel[uint64, uint64, uint64]) (s.CampaignFeedback[uint64, uint64, uint64, uint64], error) {
		emit(id, "feedback_factory")
		if name == "feedback-error" {
			return s.CampaignFeedback[uint64, uint64, uint64, uint64]{}, &s.ModelError{Message: "feedback factory error"}
		}
		f := s.Feedback[uint64, uint64, uint64, uint64]{Key: s.FeatureKey[uint64]{Clone: s.ValueCopy[uint64], Equal: func(a, b uint64) bool { return a == b }}, Metadata: func() (s.FeedbackMetadata, error) {
			emit(id, "feedback_metadata")
			if name == "feedback-metadata-panic" {
				panic("feedback metadata panic")
			}
			return s.FeedbackMetadata{Name: "n06-depth", Version: 1, Build: "n06-depth-v1"}, nil
		}, InitialFeatures: func(state uint64, out *s.FeatureBuffer[uint64]) error {
			emit(id, "feedback_initial")
			return out.Push(state)
		}, TransitionFeatures: func(_ uint64, _ uint64, t s.Transition[uint64, uint64], out *s.FeatureBuffer[uint64]) error {
			emit(id, "feedback_transition")
			return out.Push(t.State)
		}}
		return s.CampaignFeedback[uint64, uint64, uint64, uint64]{Feedback: f, Close: func() error { emit(id, "feedback_drop"); return nil }}, nil
	}
	sink := func(j s.JobReport64[uint64]) error {
		emit(j.JobID, "sink")
		jobs = append(jobs, jobJSON(j))
		if name == "sink-error" {
			return &s.ModelError{Message: "first sink error"}
		}
		if name == "sink-panic" {
			panic("sink panic")
		}
		return nil
	}
	limits := s.RunLimits{Cancellation: &cancel}
	if name == "deadline-zero" {
		d := time.Duration(0)
		limits.MaxDuration = &d
	}
	var report s.CampaignReport64
	var err error
	if guided {
		report, err = s.RunGuidedCampaign64(c, limits, s.GuidanceConfig64{MaxCorpusEntries: 2, MaxCorpusInputs: 3, MaxFeatures: 3, MaxFeaturesPerObservation: 1}, factory, feedback, sink)
	} else {
		report, err = s.RunCampaign64(c, limits, factory, sink)
	}
	if err != nil {
		return nil, true, err
	}
	return map[string]any{"schema": "native-campaign-v1", "kind": "campaign", "case": name, "config": refConfig(c), "guided": guided, "jobs": jobs, "callbacks": events, "report": reportJSON(report)}, true, nil
}

func referenceNames() []string {
	names := make([]string, 0, len(refSeeds)+len(refValidations)+len(refCampaigns))
	for i := range refSeeds {
		names = append(names, fmt.Sprintf("seed-%02d", i))
	}
	names = append(names, refValidations...)
	names = append(names, refCampaigns...)
	return names
}
